div.script:
document.getElementById('launch-btn').onclick = async function() {
  try {
    const rawUrl = "https://raw.githubusercontent.com/Mistyitz/EduForgePlatform-/main/index.html";
    const response = await fetch(rawUrl);

    if (!response.ok) throw new Error("Could not load index.html");
    const htmlCode = await response.text();

    const win = window.open('about:blank', '_blank');
    if (win) {
      win.document.open();
      win.document.write(htmlCode);
      win.document.close();
    } else {
      alert("Popup blocked! Please allow popups to launch EduWorld.");
    }
  } catch (err) {
    alert("Failed to fetch application code from GitHub.");
  }
};
